<?php
namespace App\Http\Controllers\Member;
use App\Models\Conversation;use App\Models\User;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class MessageController{
 public function index(Request $r){$items=Conversation::whereHas('participants',fn($q)=>$q->where('users.id',$r->user()->id))->with(['messages'=>fn($q)=>$q->latest()->limit(1)])->latest('updated_at')->get();return view('member.messages.index',['conversations'=>$items]);}
 public function start(Request $r){$d=$r->validate(['recipient_id'=>'required|integer|exists:users,id','body'=>'required|string|max:10000']);abort_if((int)$d['recipient_id']===$r->user()->id,422);abort_if(DB::table('user_blocks')->where(fn($q)=>$q->where(['user_id'=>$r->user()->id,'blocked_user_id'=>$d['recipient_id']])->orWhere(fn($z)=>$z->where(['user_id'=>$d['recipient_id'],'blocked_user_id'=>$r->user()->id])))->exists(),403,'Messaging unavailable for this member.');$conversation=DB::transaction(function()use($r,$d){$c=Conversation::create(['type'=>'direct']);$c->participants()->attach([$r->user()->id,$d['recipient_id']],['last_read_at'=>now()]);$c->messages()->create(['user_id'=>$r->user()->id,'body'=>$d['body'],'status'=>'sent']);return $c;});return redirect()->route('messages.show',$conversation);}
 public function show(Request $r,Conversation $conversation){abort_unless($conversation->participants()->where('users.id',$r->user()->id)->exists(),403);$conversation->participants()->updateExistingPivot($r->user()->id,['last_read_at'=>now()]);return view('member.messages.show',['conversation'=>$conversation,'messages'=>$conversation->messages()->with('user')->latest()->paginate(50)]);}
 public function store(Request $r,Conversation $conversation){abort_unless($conversation->participants()->where('users.id',$r->user()->id)->exists(),403);$d=$r->validate(['body'=>'required|string|max:10000']);$conversation->messages()->create(['user_id'=>$r->user()->id,'body'=>$d['body'],'status'=>'sent']);$conversation->touch();return back();}
}